// Validar que el evento sea un deal.updated con stage_id = 62
// y que el deal pertenezca al pipeline 6 (Bayteca)

const body = $input.first().json.body || $input.first().json;

// Pipedrive envía el evento con 'current' y 'previous' data
const current = body.current || body;
const meta = body.meta || {};

const stageId = current.stage_id || current.current_stage_id;
const pipelineId = current.pipeline_id;

if (stageId !== 62) {
  return [{ json: { skip: true, reason: `stage_id=${stageId}, expected 62` } }];
}

if (pipelineId && pipelineId !== 6) {
  return [{ json: { skip: true, reason: `pipeline_id=${pipelineId}, expected 6` } }];
}

const dealId = current.id || body.id;
if (!dealId) {
  return [{ json: { skip: true, reason: 'No deal ID found' } }];
}

return [{ json: { dealId, stageId, pipelineId, ok: true } }];

// Detectar si alguno de Bank 1–5 es Kutxabank
// Kutxabank option IDs: 2633 (B1), 2651 (B2), 2669 (B3), 2687 (B4), 2705 (B5)

const deal = $input.first().json;

const KUTXA_OPTION_IDS = [2633, 2651, 2669, 2687, 2705];

const BANK_FIELD_IDS = [
  'af536dbfe7d00fd441ae9bd4b144c25bc1d4c725',
  '8e4b44a3f3973d1f524f8cd0ec6f6babe9e96965',
  'ed0a30972778ac2c3d29cab53e27a89f5b52a1b2',
  '9049591570e78d3274a72cfb7a28076789ce0676',
  '36ff3525fb8a73637e069099967b2afe164e408a',
];
const BANK_ID_FIELD_IDS = [
  '04d666f12e4d27a3867daa5d7d6b777d76d24eb9',
  '75d8963d89d47daf37349722c531677263173484',
  '874add027adde7fa7690874e3bac581489387651',
  '467feaa56488620159ef39890e6d8f96489bdbac',
  'b3dfef96dce320a1cfa4605056757f7e79731676',
];
const BANK_LINK_FIELD_IDS = [
  'fc8312a76b8fe194ba55b60f3e09ac7e7800a5bd',
  'd78cdb37e370d21facdea787f4bd7a22520ac62d',
  'b3b1fd8fba90a455d01fb4aa4805569d4b60070a',
  '9a4d771432722d30f6e4abe8f0cee6a542793475',
  '963244c4d383295066674c693d813b4abb27ae11',
];

function parseBankDealId(raw) {
  if (raw == null) return null;
  const str = String(raw).trim();
  const n = parseInt(str, 10);
  if (!isNaN(n) && n > 0) return n;
  const m = str.match(/\/deal\/(\d+)/);
  if (m) { const id = parseInt(m[1], 10); if (!isNaN(id) && id > 0) return id; }
  return null;
}

// ── Contrato enum maps ────────────────────────────────────────────────────────
const contractType1Map = {
  2613: 'Indefinido', 2614: 'Funcionario', 2615: 'Autónomo', 2616: 'Temporal',
  2617: 'Interino', 2618: 'Fijo discontínuo', 2619: 'Desempleado',
  2620: 'Jubilado', 2863: 'Pensionista'
};
const contractType2Map = {
  2526: 'Indefinido', 2527: 'Funcionario', 2528: 'Autónomo', 2529: 'Temporal',
  2530: 'Desempleado', 2531: 'Interino', 2532: 'Fijo discontínuo', 2864: 'Pensionista'
};

function resolveEnum(rawValue, map) {
  if (!rawValue && rawValue !== 0) return '';
  const key = typeof rawValue === 'object' ? (rawValue.id ?? rawValue.value) : rawValue;
  return map[Number(key)] || String(rawValue);
}

// ── Detectar slot Kutxabank ───────────────────────────────────────────────────
let kutxaSlot = -1;
for (let i = 0; i < BANK_FIELD_IDS.length; i++) {
  const rawVal = deal[BANK_FIELD_IDS[i]];
  const numVal = rawVal != null ? parseInt(String(rawVal), 10) : NaN;
  if (!isNaN(numVal) && KUTXA_OPTION_IDS[i] === numVal) {
    kutxaSlot = i;
    break;
  }
}

if (kutxaSlot === -1) {
  return [{ json: { isKutxa: false, reason: 'Kutxabank not in Bank 1–5' } }];
}

const bankDealId =
  parseBankDealId(deal[BANK_ID_FIELD_IDS[kutxaSlot]]) ??
  parseBankDealId(deal[BANK_LINK_FIELD_IDS[kutxaSlot]]);

// ── Drive folder ──────────────────────────────────────────────────────────────
const driveUrl    = deal['c2ea08d72de437ee4957ff3807c48cebe7a1aa3e'] || '';
const folderMatch = driveUrl.match(/\/folders\/([a-zA-Z0-9_-]+)/);
const folderId    = folderMatch ? folderMatch[1].split('?')[0] : null;

// ── Datos cliente ─────────────────────────────────────────────────────────────
const dni             = deal['60228dc43313b931378ec9bb3f21f7ad7f5a144c'] || '';
const plan            = deal['b5d36c005e38a4cd72d831be655996a3d6b34dc1'] || '';
const nombreCliente   = deal.person_name || '';
const secondTitular   = deal['209a0da7966a29bf05e96b6a124536222e0318dd'] || '';

// ── Campos financieros (columnas C–H del Rastreator) ─────────────────────────
const importeCompraventa = deal['184fc13001dbca74b20c77f0fcfdec161b5cb492'] || '';
const importeHipoteca    = deal['b80d8ee37cc14ecdd7d8a640a57d6bd85308d5b9'] || '';
const ingresos1T         = deal['8e0e7ac2bd665bc3c0c5eb7d979a1ae1d9bc1300'] || '';
const contrato1T         = resolveEnum(deal['5788be4f764dabff9006ab5d685ae8061c7db3d9'], contractType1Map);
const ingresos2T         = deal['a52a8dcf3e016ffd7e670c6d888d30b4f08dc895'] || '';
const contrato2T         = resolveEnum(deal['9d6bb0a4cffae14651df0370331afa40b101c6e9'], contractType2Map);

return [{
  json: {
    isKutxa: true,
    dealId: deal.id,
    bankDealId,
    folderId,
    driveUrl,
    dni,
    plan,
    nombreCliente,
    hasSecondTitular: !!secondTitular,
    kutxaSlot,
    // Campos financieros
    importeCompraventa,
    importeHipoteca,
    ingresos1T,
    contrato1T,
    ingresos2T,
    contrato2T,
  }
}];

// Filtrar los archivos encontrados para C003–C008 y D003–D008
// y registrar los que faltan
// Input: HTTP Request → { files: [{ id, name, mimeType }] }

const info = $('Detectar Kutxabank').item.json;
const allFiles = $input.first().json.files || [];

const DOC_CODES_1T = ['C003', 'C004', 'C005', 'C006', 'C007', 'C008'];
const DOC_CODES_2T = ['D003', 'D004', 'D005', 'D006', 'D007', 'D008'];

const neededCodes = [...DOC_CODES_1T];
if (info.hasSecondTitular) neededCodes.push(...DOC_CODES_2T);

// Map filename → file
const foundFiles = {}; // code → { id, name }
const missingDocs = [];

for (const file of allFiles) {
  const fileName = file.name || '';
  for (const code of neededCodes) {
    if (fileName.includes(code) && !foundFiles[code]) {
      foundFiles[code] = { id: file.id, name: fileName };
    }
  }
}

for (const code of neededCodes) {
  if (!foundFiles[code]) missingDocs.push(code);
}

const filesToDownload = Object.values(foundFiles);

if (filesToDownload.length === 0) {
  return [{
    json: {
      ...info,
      filesToDownload: [],
      missingDocs,
      zipFilename: `Kutxabank_${info.bankDealId}_${info.nombreCliente.replace(/\s+/g, '_')}_${info.dni}.zip`,
    }
  }];
}

return filesToDownload.map((f, idx) => ({
  json: {
    ...info,
    fileId: f.id,
    fileName: f.name,
    isLastFile: idx === filesToDownload.length - 1,
    totalFiles: filesToDownload.length,
    missingDocs,
    zipFilename: `Kutxabank_${info.bankDealId}_${info.nombreCliente.replace(/\s+/g, '_')}_${info.dni}.zip`,
  }
}));

// Agregar todos los items (uno por archivo) en un único body
// para llamar al endpoint /api/kutxabank/create-zip
//
// Cada item tiene en json:
//   fileBase64  – contenido del PDF en base64 (resuelto por moveBinaryData)
//   fileName    – nombre del archivo
//   + contexto: dni, zipFilename, folderId, dealId, bankDealId...

const items = $input.all();
if (items.length === 0) {
  throw new Error('No items to zip');
}

const first = items[0].json;

const files = items.map(item => ({
  data: item.json.fileBase64,
  fileName: item.json.fileName,
}));

return [{
  json: {
    files,
    dni: first.dni,
    zipFilename: first.zipFilename,
    folderId: first.folderId,
    dealId: first.dealId,
    bankDealId: first.bankDealId,
    nombreCliente: first.nombreCliente,
    missingDocs: first.missingDocs || [],
    fileCount: files.length,
    // financieros
    importeCompraventa: first.importeCompraventa,
    importeHipoteca: first.importeHipoteca,
    ingresos1T: first.ingresos1T,
    contrato1T: first.contrato1T,
    ingresos2T: first.ingresos2T,
    contrato2T: first.contrato2T,
  }
}];

// Restaurar contexto JSON + pasar el binario ZIP al nodo de subida.
// El HTTP Request anterior devolvió el ZIP como binary;
// este nodo lo combina con el contexto de 'Preparar solicitud ZIP'.

const ctx = $('Preparar solicitud ZIP').first().json;

return [{
  json: {
    dealId:          ctx.dealId,
    bankDealId:      ctx.bankDealId,
    folderId:        ctx.folderId,
    zipFilename:     ctx.zipFilename,
    nombreCliente:   ctx.nombreCliente,
    dni:             ctx.dni,
    missingDocs:     ctx.missingDocs || [],
    fileCount:       ctx.fileCount || 0,
    zipCreated:      true,
    importeCompraventa: ctx.importeCompraventa,
    importeHipoteca:    ctx.importeHipoteca,
    ingresos1T:         ctx.ingresos1T,
    contrato1T:         ctx.contrato1T,
    ingresos2T:         ctx.ingresos2T,
    contrato2T:         ctx.contrato2T,
  },
  binary: $input.first().binary   // referencia filesystem-v2 del ZIP — Drive lo resuelve
}];

// Construir el link de Drive y preparar datos para Supabase y Rastreator
const zipInfo = $('Crear ZIP').item.json;
const uploadResult = $input.first().json;

const zipFileId = uploadResult.id || uploadResult.fileId || '';
const zipDriveLink = zipFileId
  ? `https://drive.google.com/file/d/${zipFileId}/view`
  : '';

return [{
  json: {
    ...zipInfo,
    zipFileId,
    zipDriveLink,
  }
}];

